<?php
namespace App\Services;
use App\Models\Payment; use App\Models\Receipt; use Illuminate\Support\Facades\DB; use Illuminate\Support\Str;
class PaymentService { public function verify(Payment $payment,array $payload):Payment{return DB::transaction(function()use($payment,$payload){$payment->refresh();if($payment->status==='success')return $payment;if(($payload['status']??'')!=='success'){$payment->update(['status'=>in_array($payload['status']??'', ['failed','cancelled'])?$payload['status']:'failed','gateway_payload'=>$payload]);return $payment;}$payment->update(['status'=>'success','gateway_transaction_id'=>$payload['transaction_id']??('TXN-'.strtoupper(Str::random(10))),'paid_at'=>now(),'gateway_payload'=>$payload]);$payment->application->update(['status'=>'paid']);Receipt::firstOrCreate(['yellow_page_application_id'=>$payment->yellow_page_application_id],['reference'=>'RCT-'.now()->format('Ymd').'-'.strtoupper(Str::random(6)),'verification_token'=>(string)Str::uuid()]);return $payment;});}}
